-- Migration 0017 — Phase 8: shared-phone-number conversation ownership
-- (gap register A1, A2, A3, A4, D12; D16 "conversation unique key" bullet).
--
-- Generated by `drizzle-kit generate` from src/schema/{conversations,
-- messaging-profiles,inbound-routing}.ts; this header, the address
-- normalisation UPDATEs and the add-new-key-before-dropping-old-key ordering
-- were added by hand.
--
-- 1. conversations gains the ownership fields it never had: business_number
--    (the shared/dedicated number the conversation is ON — previously not
--    recorded anywhere), supplier_id, messaging_profile_id, country,
--    workflow_id (placeholder). Existing rows keep business_number NULL: the
--    number they were on was never recorded, and is NOT guessed here. The
--    Phase 8 resolver treats a NULL-number row as legacy evidence only.
-- 2. Unique key (phone_number, app_id, tenant_id) is replaced by
--    (phone_number, business_number, app_id, tenant_id, supplier_id)
--    NULLS NOT DISTINCT (PostgreSQL >= 15).
-- 3. messaging_profiles gains supplier_id and a (sender, provider) index —
--    the inbound path now resolves destination number → owners through it.
-- 4. inbound_message_holds: quarantine for inbound messages that cannot be
--    attributed to exactly one owner (never delivered to a guessed tenant,
--    never silently dropped).
-- 5. sender_opt_outs: STOP recorded at the shared-number level.
--
-- No existing row is deleted or merged.

CREATE TABLE "inbound_message_holds" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"dedupe_key" text NOT NULL,
	"provider_id" text NOT NULL,
	"customer_phone" text NOT NULL,
