	"channel" text DEFAULT 'sms' NOT NULL,
	"content" text NOT NULL,
	"keyword" text,
	"reason" text NOT NULL,
	"candidates" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"sender_opt_out_applied" boolean DEFAULT false NOT NULL,
	"raw_payload" jsonb,
	"resolved_app_id" text,
	"resolved_tenant_id" text,
	"resolved_supplier_id" text,
	"resolved_by" text,
	"resolution_note" text,
	"resolved_at" timestamp with time zone,
	"delivered_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "chk_inbound_holds_status" CHECK ("inbound_message_holds"."status" IN ('pending', 'resolved', 'delivered', 'discarded')),
	CONSTRAINT "chk_inbound_holds_reason" CHECK ("inbound_message_holds"."reason" IN ('ambiguous_owner', 'no_owner'))
);
