-- Normalise stored addresses to the same canonical form the Phase 8 code
-- writes and looks up with (packages/database/src/messaging-address.ts):
-- strip a 'whatsapp:'/'sms:'/'tel:' scheme and spaces, dashes, dots and
-- parentheses when what remains is a phone number / short code. Alphanumeric
-- sender IDs are left untouched. A row whose normalised form would collide
-- with an existing row is left as it is (never merged, never deleted).
WITH n AS (
  SELECT "id", "app_id", "tenant_id", "provider", "sender",
    regexp_replace(regexp_replace(btrim("sender"), '^(whatsapp|sms|tel):', '', 'i'), '[[:space:]().-]', '', 'g') AS normalized
  FROM "messaging_profiles"
)
UPDATE "messaging_profiles" AS mp
SET "sender" = n.normalized
FROM n
WHERE mp."id" = n."id"
  AND n.normalized ~ '^\+?[0-9]+$'
  AND n.normalized <> n."sender"
  AND NOT EXISTS (
    SELECT 1 FROM n o
    WHERE o."id" <> n."id" AND o."app_id" = n."app_id" AND o."tenant_id" = n."tenant_id"
      AND o."provider" = n."provider" AND (o."sender" = n.normalized OR o.normalized = n.normalized)
  );--> statement-breakpoint
WITH n AS (
  SELECT "id", "app_id", "tenant_id", "phone_number",
    regexp_replace(regexp_replace(btrim("phone_number"), '^(whatsapp|sms|tel):', '', 'i'), '[[:space:]().-]', '', 'g') AS normalized
  FROM "conversations"
)
UPDATE "conversations" AS c
SET "phone_number" = n.normalized
FROM n
WHERE c."id" = n."id"
  AND n.normalized ~ '^\+?[0-9]+$'
  AND n.normalized <> n."phone_number"
  AND NOT EXISTS (
    SELECT 1 FROM n o
    WHERE o."id" <> n."id" AND o."app_id" = n."app_id" AND o."tenant_id" = n."tenant_id"
      AND (o."phone_number" = n.normalized OR o.normalized = n.normalized)
  );--> statement-breakpoint
